/** Look up a backstory by ticker. Strips leading $ and uppercases. Returns undefined if not found. */
export function getBackstory(ticker: string): CoinBackstory | undefined {
  const key = ticker.replace(/^\$/, '').toUpperCase();
  return ALL_BACKSTORIES[key];
}
